 payload jsonb := $correcciones36${"patches": [{"numero": "Q023", "input": {"id": "b1fe719e-f34d-4c60-91ca-f6d235036f1c", "revision": 0, "prompt": "Una contratación no programada tiene su necesidad incluida en el CMN respectivo y la DEC recibe el requerimiento del área usuaria. Según el numeral 42.3 modificado, ¿cuándo efectúa la segmentación?", "options": [{"id": "A", "text": "Luego de recibir el requerimiento."}, {"id": "B", "text": "Después de otorgar la buena pro."}, {"id": "C", "text": "Al finalizar la ejecución contractual."}, {"id": "D", "text": "Solo al aprobar una nueva modificación del CMN."}], "correctOption": "A", "explanation": "Con la necesidad incluida en el CMN respectivo, la DEC efectúa la segmentación luego de recibir el requerimiento. No basta una mera solicitud de modificación del CMN ni se espera a la selección.", "regime": "32069", "topic": "Requerimiento, estrategia y mercado", "competency": "Actuaciones preparatorias", "difficulty": "intermediate", "curriculumVersion": "oece-2025-04-25", "competencyCode": "1", "subcompetencyCode": "1.2", "cognitiveLevel": "apply", "optionRationales": {"A": "Con la necesidad incluida en el CMN respectivo, la DEC efectúa la segmentación luego de recibir el requerimiento. No basta una mera solicitud de modificación del CMN ni se espera a la selección.", "B": "No corresponde: la buena pro es posterior al hito consultado.", "C": "No corresponde: la ejecución contractual no es el hito de segmentación.", "D": "No corresponde: no se exige otra modificación si la necesidad ya está incluida."}, "reviewChecks": {"unambiguous": false, "distractors": false, "conditions": false, "exceptions": false, "sources": false}, "sourceCutoff": "2026-10-29", "origin": "IA:gemini:gemini-2.5-flash:lote:d0d33e34-988f-4c22-bf94-617ea347a237", "sources": [{"documentId": "8371bce1-f773-4ad8-8efa-1266276ae4ec", "chunkId": "2af95311-29f7-4432-9c43-9abfad7ba2c7", "title": "Reglamento de la Ley N.° 32069 — texto actualizado al 09.01.2026", "ar